S_5 = [
('robotics', 'Robotics', [
('Pick one task in one workplace, such as moving boxes in a small store room, and define it in numbers.', 'Task card: carry 20 kg boxes over 30 m, 100 times per day, in a dry indoor room.'),
('Compare three models: sell robots, rent robots by the month, or sell a service done by robots. Choose by cash needed.', 'Sell {c} 8000 once, rent {c} 400 per month, service {c} 5 per box: compare after 12 months of use.'),
('List the safety rules, electrical standards, import rules and worker rules that apply before a trial.', 'Rules table: machine safety check, emergency stop, test report, insurance note; each has a date checked.'),
('Log robot data, camera images and error records; keep images of people private and delete them on a set date.', 'Rule: camera images are deleted after 14 days; error logs are kept for 1 year.'),
('Run a 2-week trial at a customer site and measure time saved and errors.', 'Trial result: 100 boxes moved per day, 3 errors, 2 hours of staff time saved per day.'),
('Price by parts, build time, support and spares; test the price against the customer saving.', 'Parts 5000, build 40 hours at {c} 25 = 1000, support 500: cost 6500; sale price 8000 leaves 1500.'),
('Partner with a machine shop, a parts supplier and a trained service technician; write who fixes what.', 'Service sheet: supplier ships spares in 3 days; technician visits within 48 hours.'),
('Launch with 3 pilot sites and a go or no-go rule on uptime and savings.', 'Go rule: robot works 95% of shifts and saves 20% of task cost at 2 of 3 sites; else fix the design first.'),
]),
('online-medical-supply', 'Online Medical Supply and Equipment Provider', [
('Start with one low-risk product group, such as walking aids or home care supplies, for one customer type.', 'Start with 15 items for elderly home carers; drop items with no orders after 6 weeks.'),
('Compare models: own shop, supply to clinics, or ordering through a licensed pharmacy partner. Pick by risk and margin.', 'Own shop margin 25% with high duty of care; clinic supply margin 15% with large orders; compare both.'),
('Planning only: list which items need a licence or a regulator approval and ask a licensed firm or the regulator before selling.', 'Licence table: item, class, who may sell, label needs, returns rule, date checked; sell only items marked clear.'),
('Treat health and order data as sensitive: collect the minimum, restrict access, and never share it for marketing.', 'Access list: 2 staff see orders; no one sees health notes unless the buyer gave consent in writing.'),
('Show product details, use guide and returns rule on each page; add a partner clinic reference.', 'Page test: 200 visitors, 10 orders, a 5% rate; add a size guide and test again.'),
('Count landed cost: product, import, storage, delivery, returns share, payment fee.', 'Item 60, import 6, storage 4, delivery 10, returns 5, fee 3: landed 88; price 120 leaves 32.'),
('Partner with a licensed supplier, a delivery firm and a trained advisor who checks fit; write each duty.', 'Duty sheet: supplier gives batch records; advisor checks the order within 1 day.'),
('Launch with a go or no-go rule on safe delivery and return rate.', 'Go rule: 40 orders in 8 weeks, returns under 5%, no safety complaint; else pause and fix.'),
]),
('car-sharing', 'Car Sharing Business', [
('Start with one district and one group, such as students or office workers without a car.', 'Pilot: 5 cars in one district, 100 members invited, bookings by phone app or message.'),
('Compare models: own fleet, owner-shared cars, or partner with a rental firm. Pick by cash needed per hour of use.', 'Own car {c} 10000 upfront; owner share pays the owner 60% of hire income; rental partner needs no cars.'),
('Check the vehicle licence, passenger insurance, driver checks and local transport rules before the first booking.', 'Rules table: shared use cover, driver licence check, vehicle fitness date, parking permit; each dated.'),
('Store driver licence images and location data safely; keep trip data only as long as needed.', 'Rule: location traces deleted after 30 days; licence copies deleted when a member leaves.'),
('Run a 4-week pilot and measure use per car and complaints.', 'Pilot result: each car used 6 hours per day out of 24, a 25% use rate; 2 complaints in 120 trips.'),
('Price by hour and day; count fuel, cleaning, insurance, car cost and repairs.', 'Per car per month: cost 600, cleaning 60, insurance 120: 780; 6 h x 30 days x {c} 6 = 1080 income, leaves 300.'),
('Partner with a garage, a cleaner and a parking owner; write response times.', 'Garage fixes faults in 2 days; cleaner visits every 3 days.'),
('Launch with a go or no-go rule on use rate and damage cost.', 'Go rule: 25% use rate or higher and damage cost under 5% of income for 8 weeks; else cut cars.'),
]),
('bpo', 'Business Process Outsourcing Services', [
('Sell one process for one client type, such as invoice entry for small firms.', 'Offer: enter 500 invoices per month in 2 days with a 99% accuracy target.'),
('Compare models: price per task, monthly team, or shared back office. Pick by risk and steady income.', 'Per task {c} 0.50; team of 3 at {c} 3000 per month; compare income at 4000 tasks.'),
('Check contract terms, data protection law, tax set-up and labour rules before taking client work.', 'Rules table: service contract, data law note, work permit rule, overtime rule; each dated.'),
('Set access rules: client data stays in client systems, staff sign confidentiality notes, logs are kept.', 'Access sheet: each worker sees only their own client folder; logins reviewed every month.'),
('Run a paid pilot on 100 tasks and report accuracy and time.', 'Pilot: 100 invoices, 98 right first time, 2 fixed; average 3 minutes each.'),
('Price per task from staff cost, tools, checks and margin.', 'Staff cost {c} 1000 per month, 2000 tasks: 0.50 each; add tools 0.10, checks 0.10: cost 0.70; price 1.00 leaves 0.30.'),
('Hire and train staff in small teams; add a team lead who checks quality; write the training plan.', 'Training: 5 days, test on 50 tasks, pass at 95% accuracy.'),
('Launch with a go or no-go rule on accuracy and margin.', 'Go rule: 95% accuracy and 25% margin over 4 weeks of live work; else retrain before taking more clients.'),
]),
('stem-cell-therapy', 'Stem Cell Therapy', [
('Planning only: define the problem you want to help, such as patient information or clinic support, not treatment.', 'Scope note: we explain options and book visits; a licensed clinic gives all treatment.'),
('Compare models: referral to a licensed clinic, patient education service, or research support partner. Pick the one with no clinical duty.', 'Referral desk needs no lab; education service needs trusted content; compare risk and cost.'),
('Check which treatments are approved, who may offer them and what claims are banned; ask the regulator and a licensed firm first.', 'Rules table: approved uses, claim limits, consent rules, advertising rules, date checked; never promise a cure.'),
('Treat all health records as highly sensitive; collect nothing you do not need and get written consent.', 'Record rule: only the clinic holds medical records; we hold name and contact with consent.'),
('Show proof from the partner clinic: licence, approvals and published study summaries, not patient stories as promises.', 'Proof page: licence number, approval date, 3 study summaries with plain notes on limits.'),
('Plan money for a service role: fees to the patient are set by the partner and shown in full.', 'Desk cost: 2 staff at {c} 1500 each plus tools 500 = 3500 per month; 35 booked visits at {c} 100 = 3500, break even.'),
('Partner with a licensed clinic, a genetic counsellor and a patient group; write who owns each duty.', 'Duty sheet: clinic gives treatment and consent; we give information and booking only.'),
('Launch with a go or no-go rule on legal sign-off and patient trust.', 'Go rule: written sign-off from the regulator or legal firm and the clinic; if missing, do not launch.'),
]),
('home-sharing', 'Home Sharing', [
('Start with one area and one guest type, such as visiting families or workers on short jobs.', 'Pilot: list 10 rooms near one hospital area for stays of 3 to 14 nights.'),
('Compare models: list homes for a fee, manage homes for owners, or run leased homes. Pick by risk.', 'List fee needs no assets; managing earns 15% of income; leasing carries rent risk.'),
('Check short-stay rules, tax on rental income, safety checks and building rules before listing.', 'Rules table: stay permit, tax note, fire safety, neighbour or building rule; each dated.'),
('Verify hosts and guests, store IDs safely, and keep message records for disputes.', 'Check: host proof of ownership; guest ID seen but not stored after checkout.'),
('Show real photos, house rules and guest reviews on each listing.', 'Listing with 12 photos and 5 reviews gets 4 enquiries per week against 1 for a bare one.'),
('Price per night and count cleaning, supplies, fees and empty nights.', 'Rent {c} 50 per night, 18 nights booked = 900; cleaning 120, supplies 40, platform fee 90: costs 250; leaves 650.'),
('Partner with cleaners, key handlers and a repair person; write call-out times.', 'Cleaner finishes within 3 hours of checkout; repairs within 24 hours.'),
('Launch with a go or no-go rule on occupancy and complaints.', 'Go rule: 50% of nights booked and under 1 complaint per 20 stays for 8 weeks; else stop adding homes.'),
]),
('crowdfunding', 'Crowdfunding Platform', [
('Start with one campaign type and one community, such as local creative projects.', 'Pilot: 5 projects with goals of {c} 2000 to 5000 from one town.'),
('Compare models: rewards, donations, or lending and shares through a licensed partner. Pick the lightest rule burden.', 'Rewards and donations have fewer rules; lending and shares need a licence, so partner with a licensed firm.'),
('Planning only: list which models need a financial licence and ask a licensed firm and the regulator before taking money.', 'Rules table: model, who may hold funds, backer protection, refund rule, tax note; dated.'),
('Verify project owners, protect backer data and use a licensed payment partner to hold funds.', 'Check: ID and plan review for each owner; payments held by the partner until the goal is met.'),
('Show project updates, budgets and proof of past delivery on every campaign page.', 'Page shows budget in 5 lines, 3 updates and a delivery date.'),
('Plan platform income and costs; check the maths with a pilot.', 'Raised {c} 10000 in total; a 5% platform share is 500, payment costs 3% = 300, leaves 200; costs of tools and support also need cover.'),
('Partner with a licensed payment firm, a legal adviser and community groups for reach.', 'Duty sheet: payment firm holds funds; adviser reviews terms; groups share campaigns.'),
('Launch with a go or no-go rule on funded projects and delivery.', 'Go rule: 3 of 5 pilot projects reach their goal and deliver on time; else fix vetting.'),
]),
('online-library', 'Online Library', [
('Start with one subject and one reader group, such as exam books for secondary students.', 'Pilot: 200 titles for one grade, free to read for 30 days.'),
('Compare models: subscription, pay per book, or school licence. Choose by steady income.', 'Subscription {c} 3 per month, per book {c} 1, school licence {c} 500 per year: compare at 300 readers.'),
('Check copyright rules and written permission for every title; list public domain items separately.', 'Rights table: title, owner, permission date, end date, territory; no title goes live without a row.'),
('Protect reader accounts and reading records; collect only email and class level.', 'Rule: reading history is kept 90 days and never sold; children accounts need a parent consent.'),
('Show reader proof: pages read, books finished and teacher feedback.', 'Pilot: 120 readers, 60 finished at least 1 book in 4 weeks, a 50% rate.'),
('Price access and count content rights, hosting and support.', 'Rights {c} 400, hosting 100, support 200: costs 700 per month; 300 readers at {c} 3 = 900 leaves 200.'),
('Partner with publishers, teachers and a hosting provider; write each duty.', 'Publisher gives files and permission; teacher picks lists; host keeps the site up 99% of the time.'),
('Launch with a go or no-go rule on active readers and renewals.', 'Go rule: 40% of readers active each week and 60% renew after month 1; else fix content first.'),
]),
('portable-charging-station', 'Portable/Powermat Charging Station', [
('Start with one busy place type, such as cafes, and one charger design.', 'Pilot: 10 tables in 3 cafes with wireless charging pads.'),
('Compare models: sell units, rent per month, or free with a shared advertising fee. Pick by cash.', 'Sell {c} 80 per unit; rent {c} 6 per month; ads {c} 3 per unit per month; compare at 100 units.'),
('Check electrical safety marks, radio rules, import rules and venue insurance before install.', 'Rules table: safety mark, radio test, import check, venue consent; each dated.'),
('Collect only usage counts; avoid phone data and tell users clearly.', 'Counter logs charges per day; no phone name or number is stored.'),
('Run a 4-week pilot and measure sessions and venue feedback.', 'Pilot: 10 tables, 8 charges per table per day, 2 faults in 4 weeks.'),
('Price per unit and count parts, assembly, shipping and repair share.', 'Parts 40, assembly 6, shipping 5, repair share 4: cost 55; sell 80 leaves 25; 100 units give 2500.'),
('Partner with a parts maker, a shipper and venue staff; write repair times.', 'Venue reports faults by message; swap unit in 3 days.'),
('Launch with a go or no-go rule on use and fault rate.', 'Go rule: 5 charges per table per day and under 3% faults over 4 weeks; else redesign.'),
]),
('plastic-alternatives', 'Plastic Alternatives', [
('Replace one plastic item for one buyer, such as takeaway boxes for food stalls.', 'Pilot: plant-fibre box for 10 street food stalls.'),
('Compare materials and models: make, buy and resell, or license a method. Pick by cost and supply.', 'Make needs a machine; resell needs a supplier; compare per box cost at 10000 boxes.'),
('Check food contact rules, claim rules on words like compostable, waste rules and import rules.', 'Rules table: food-safe test, claim wording, waste handling, import code; each dated.'),
('Keep batch records and test reports so each claim has proof.', 'Batch sheet: date, material source, test result, quantity; kept for 2 years.'),
('Run a stall trial and measure leaks, heat and customer opinion.', 'Trial: 500 boxes, 6 leaks, 92% of customers rated it good.'),
('Price per piece against plastic; count material, labour, waste and delivery.', 'Material 0.12, labour 0.03, waste 0.01, delivery 0.02: cost 0.18; sell 0.25 leaves 0.07; 10000 boxes give 700.'),
('Partner with a material supplier, a test lab and a waste collector; write duties.', 'Supplier gives a batch report; lab tests each lot; collector takes used boxes.'),
('Launch with a go or no-go rule on repeat orders and quality.', 'Go rule: 7 of 10 stalls reorder and leaks under 2%; else change the material.'),
]),
('mobile-app-testing', 'Mobile Application Testing Services', [
('Offer one test type for one app owner group, such as bug tests for small shops apps.', 'Offer: 2-day test on 5 phones and a bug list with screenshots.'),
('Compare models: fixed test pack, monthly retainer, or per bug fee. Pick by steady income.', 'Pack {c} 400 each; retainer {c} 900 per month; per bug {c} 10; compare at 4 apps per month.'),
('Check contract terms, access rules to client builds and test data rules.', 'Contract lists scope, test dates, report format, secrecy and who owns the report.'),
('Handle pre-release apps with care: secure storage, no sharing, delete builds after the test.', 'Rule: builds deleted 14 days after the final report; access list kept.'),
('Build proof: test one open app and publish a sample report with fixes.', 'Sample report: 18 bugs found, 3 critical, each with steps and a screenshot.'),
('Price by days of work and device cost; check the margin.', '2 days at {c} 120 = 240; device use 40; report time 40: cost 320; pack price 400 leaves 80.'),
('Add testers per device type and language; write a checklist and daily hand-over.', 'Tester pool: 3 part-time testers, each owns 2 device types and reports by 5 pm.'),
('Launch with 3 pilot clients and a go or no-go rule.', 'Go rule: 2 of 3 clients rate the report useful and book a second test in 30 days.'),
]),
]
